INSERT INTO `products` (`id`, `title`, `user_id`, `description`, `price`, `state`, `category_id`) VALUES
(1, 'Gorilla couch', 1, 'Durable Construction : Crafted with a sturdy frame and high-quality materials, this sofa is designed for long-lasting use.\r\n\r\nSpacious Seating : With its generous dimensions, the sofa provides ample space for lounging or entertaining guests.\r\n\r\nPlayful Gorilla Shape : Stand out with a sofa that features a distinctive Gorilla shape and vibrant hues. This whimsical design brings a fun and unique element to any room.\r\n\r\nVersatile Style: The sleek and modern design complements various decor styles, making it a versatile addition to any living space.\r\n\r\nEasy Maintenance: The sofa\'s upholstery is easy to clean, ensuring a fresh and inviting appearance for years to come.', '1.00', 'unavailable', 4),
(2, 'Ryzen 5 Gaming PC - 6600 XT', 1, 'Condition\r\nNew\r\nIs for gaming (Y/N)\r\nYes\r\nForm factor\r\nMATX\r\nProcessor type\r\nAMD\r\nWindows 11 + Microsoft Office 365 installed & activated.\r\n\r\nSpecs: \r\n- Ryzen 5 3500X + Wraith Stealth cooler\r\n- Red Devil RX 6600 XT (8GB)\r\n- 16GB DDR4 RAM\r\n- 512GB NVMe SSD\r\n- 730W Bronze PSU\r\n- Antec Aquarium style case\r\n- 5x ARGB controllable fans\r\n\r\nPretoria East. Can courier at buyer\'s expense.\r\n\r\nSerious buyers only. Scammers stay away', '1.00', 'available', 1),
(3, ' BMW e31 850i Auto', 2, 'Its with a heavy heart that i put my 1992 BMW 850i V12 up for sale. \r\n\r\nIf you know these cars, this is the rare 8 digit vin SA model that\'s sought after the world over. \r\n\r\nI have owner the car for almost 10 years.\r\n\r\nMileage is 145 000km\r\n\r\nVehicle was maintained by BMW master technician Dave Robinson. Who has the vehicles full history on file.\r\n\r\nPowersteering \r\n\r\nAircon \r\n\r\nMemory seats \r\n\r\nCentral locking \r\n\r\nElectric mirrors\r\n\r\nSunroof\r\n\r\n1 touch windows \r\n\r\n142000km i redid Complete suspension front and rear.\r\n\r\nNew batteries x2  \r\n\r\nNew computer box\r\n\r\nNew Distributor caps\r\n\r\nNew plugs\r\n\r\nNew leads\r\n\r\nNew sump gasket\r\n\r\nNew oil and filter. Changed yearly.\r\n\r\nCustom air suspension with double bellow bags \r\n\r\nFull bluetooth management with controls on ur phone or via remote\r\n\r\n18 inch M Parallel reps with brand new tyres\r\n\r\nPeriod correct JVC Cassette Radio with 12 disk shuttle\r\n\r\nFaults\r\n\r\nDrivers seat motor ( x1 ) not working\r\n\r\nRear view mirror damaged \r\n\r\nInterior mirror panel missing\r\n\r\nAlarm doesn\'t activate if car is locked on drivers side \r\n\r\nDrivers side fender lining missing \r\n\r\nOnly 1 key \r\n\r\nReason for sale.\r\n\r\nCar doesn\'t get driven as much as it should.\r\n\r\nThis is not an urgent sale.\r\n\r\nDo not contact me for:\r\n\r\nSwaps\r\n\r\nIf you a dealer or want to sell on consignment \r\n\r\nIf u going to offer anything under 525k\r\n\r\nI will remove the ad once car is sold. \r\n\r\nR525 000 not neg \r\n\r\nPaper and disk up 2 date ', '525000.00', 'available', 2),
(4, 'Chess Set. Hand carved stone set', 2, 'Condition\r\nUsed – good', '500.00', 'available', 10),
(5, ' Nintendo Switch OLED', 4, 'Condition\r\nUsed – like new\r\nGREAT CONDITION\r\n\r\nNintendo Switch OLED \r\nPurchased in Japan so it’s as original as it gets. \r\n\r\nWhat’s in the box: \r\nNintendo Switch OLED Console \r\nDocking Station with all cabling\r\n2x Joy-Con Controllers with Adapters \r\n1x Handheld Controller \r\n1x Hardcase Carry Cover\r\n1x Mario Party Superstars \r\n1x The Legend of Zelda Tears of The Kingdom', '5700.00', 'available', 1);

